$request=static function(string $path,?array $post=null,?string $cookie=null,?string $jar=null)use($base):array{$headers=[];$ch=curl_init(rtrim($base,'/').'/'.$path);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_TIMEOUT=>20,CURLOPT_HEADERFUNCTION=>static function($ch,$line)use(&$headers){$parts=explode(':',$line,2);if(count($parts)===2){$headers[strtolower(trim($parts[0]))]=trim($parts[1]);}return strlen($line);}]);if($cookie!==null){curl_setopt($ch,CURLOPT_COOKIE,$cookie);}if($jar!==null){curl_setopt($ch,CURLOPT_COOKIEFILE,$jar);curl_setopt($ch,CURLOPT_COOKIEJAR,$jar);}if($post!==null){curl_setopt($ch,CURLOPT_POST,true);curl_setopt($ch,CURLOPT_POSTFIELDS,http_build_query($post));}$body=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$err=curl_error($ch);curl_close($ch);if($body===false){throw new RuntimeException($err);}return [$code,$body,$headers];};
